import { Capacitor, WebView } from '@capacitor/core';
import { Directory, Filesystem } from '@capacitor/filesystem';
import { Preferences } from '@capacitor/preferences';
import CryptoJS from 'crypto-js';
import JSZip from 'jszip';
import GlobalStore from "../config/GlobalStore";
import { SET_HOT_UPDATE_ENABLED, SET_HOT_UPDATE_MODAL_PROGRESS, SET_NEW_VERSION, SET_SHOW_HOT_UPDATE_MODAL } from '../reducers/hotUpdateReducer';
import { AppDispatch, RootState } from '../store';

/* ------------------------------------------------------------------ */
/* Constants                                                          */
/* ------------------------------------------------------------------ */
const LOCAL_VERSION_KEY = 'buildVersion';
/* ------------------------------------------------------------------ */
/* Version helpers                                                    */
/* ------------------------------------------------------------------ */

function waitForApiUrl(): Promise<void> {
    return new Promise((resolve) => {
        const interval = setInterval(() => {
            if (GlobalStore.apiUrl) {
                clearInterval(interval);
                resolve();
            }
        }, 100);
    });
}

export const DEFAULT_VERSION = process.env.REACT_APP_VERSION || "2.0.0";

// WebView 實際在服務的目錄：內建資源不含 update_<ver>，熱更新資料包一定含；非原生或問不到回 null
async function getActiveServerBasePath(): Promise<string | null> {
    if (!Capacitor.isNativePlatform()) return null;
    try {
        const { path } = await WebView.getServerBasePath();
        return path ?? '';
    } catch (err) {
        console.warn('[OTA] 取不到 serverBasePath', err);
        return null;
    }
}

// 永續化失敗就代表這次更新撐不過下次啟動，重試一次再放棄
async function persistServerBasePathWithRetry(): Promise<boolean> {
    for (let attempt = 1; attempt <= 2; attempt++) {
        try {
            await WebView.persistServerBasePath();
            console.log('[OTA] BasePath 已永續化 ✅');
            return true;
        } catch (err) {
            console.error(`[OTA] 永續化失敗 ❌（第 ${attempt} 次）`, err);
            if (attempt < 2) await new Promise((r) => setTimeout(r, 300));
        }
    }
    return false;
}

// 資料包還在卻沒被服務時重新套用並重載（退版號會害使用者跳回舊版又被要求更新）
async function reapplyServerBasePath(version: string): Promise<boolean> {
    if (!Capacitor.isNativePlatform()) return false;
    try {
        const { uri } = await Filesystem.stat({
            directory: Directory.Cache,
            path: `update_${version}/build/index.html`,
        });
        const basePath = uri.replace(/^file:\/\//, '').replace(/\/index\.html$/, '');
        await WebView.setServerBasePath({ path: basePath });
        await persistServerBasePathWithRetry();
        console.log(`[OTA] 資料包 ${version} 仍完整，已重新套用 basePath 並重載`);
        window.location.reload();
        return true;
    } catch (err) {
        console.warn(`[OTA] 資料包 ${version} 無法重新套用，將退回內建版本`, err);
        return false;
    }
}

export async function fetchRemoteVersion(): Promise<string> {
    // await waitForApiUrl();
    // 避免 WebView／CDN／電信商代理快取住舊的 version.json，導致判斷成需要更新到過期版本
    const VERSION_URL = `${GlobalStore.apiUrl}static/jmapp3apk/version.json?t=${Date.now()}`;
    const res = await fetch(VERSION_URL, { cache: 'no-store' });
    const data = await res.json();
    const remote = data.version ?? DEFAULT_VERSION;

    // 防呆：鏡像還沒同步時，版本可能比內建的還舊，視為無效
    if (isNewerVersion(DEFAULT_VERSION, remote)) {
        console.warn(`[OTA] 遠端版本 ${remote} 比內建版本 ${DEFAULT_VERSION} 還舊，判定為未同步的過期鏡像，忽略`);
        return DEFAULT_VERSION;
    }

    return remote;
}

export async function getLocalVersion(): Promise<string> {
    let { value } = await Preferences.get({ key: LOCAL_VERSION_KEY });

    // 防呆：reload 後 bridge 可能還沒就緒，Preferences 偶爾撲空，稍等再讀一次
    if (!value) {
        await new Promise((resolve) => setTimeout(resolve, 300));
        value = (await Preferences.get({ key: LOCAL_VERSION_KEY })).value;
    }

    const stored = value ?? DEFAULT_VERSION;

    // 保底：部分裝置（尤其 Samsung）會把舊安裝的 Preferences 備份還原回來，使版本誤判為舊版
    if (isNewerVersion(DEFAULT_VERSION, stored)) {
        await setLocalVersion(DEFAULT_VERSION);
        return DEFAULT_VERSION;
    }

    // 保底二：stored 高於實際在跑的 bundle 版本（DEFAULT_VERSION）代表資料包已失效、正跑內建資源，不拉回來的話 remote === stored 會永久卡在舊版
    if (isNewerVersion(stored, DEFAULT_VERSION)) {
        // basePath 只用來排除 runOtaFlow 已切路徑、還沒 reload 的競態；問不到就以版號為準
        const activePath = await getActiveServerBasePath();
        const servingStored = activePath !== null && activePath.includes(`update_${stored}`);
        if (!servingStored) {
            // 資料包還在就先修好，不要退版號
            if (await reapplyServerBasePath(stored)) return stored;

            console.warn(
                `[OTA] 紀錄版本 ${stored} 高於實際執行版本 ${DEFAULT_VERSION}` +
                `（basePath=${activePath}），資料包已失效，重設版本以重新觸發熱更新`
            );
            await Preferences.remove({ key: `update_${stored}` });
            await setLocalVersion(DEFAULT_VERSION);
            return DEFAULT_VERSION;
        }
    }

    return stored;
}

export async function setLocalVersion(v: string) {
    await Preferences.set({ key: LOCAL_VERSION_KEY, value: v });
}

export function isNewerVersion(remote: string, local: string): boolean {
    const r = remote.split('.').map(Number);
    const l = local.split('.').map(Number);
    while (r.length < 3) r.push(0);
    while (l.length < 3) l.push(0);

    for (let i = 0; i < 3; i++) {
        if (r[i] > l[i]) return true;
        if (r[i] < l[i]) return false;
    }
    return false;
}

export async function needUpdate(): Promise<string> {
    const [remote, local] = await Promise.all([fetchRemoteVersion(), getLocalVersion()]);
    if (isNewerVersion(remote, local)) {
        return remote;
    }
    return '';
}


/* ------------------------------------------------------------------ */
/* Download build.zip                                                 */
/* ------------------------------------------------------------------ */

async function downloadBuildZip(onProgress?: (ratio: number) => void): Promise<ArrayBuffer> {
    // await waitForApiUrl();
    const ZIP_URL = `${GlobalStore.apiUrl}static/jmapp3apk/build.enc?v=${process.env.REACT_APP_VERSION}`;
    const res = await fetch(ZIP_URL);
    if (!res.ok) throw new Error(`Download failed: ${res.status} ${res.statusText}`);

    const total = Number(res.headers.get('content-length')) || 0;
    // 拿不到 stream 或長度就退回一次性讀取
    if (!res.body || !total) return await res.arrayBuffer();

    // 串流讀取，讓下載期間進度條能持續前進
    const reader = res.body.getReader();
    const chunks: Uint8Array[] = [];
    let received = 0;
    for (; ;) {
        const { done, value } = await reader.read();
        if (done) break;
        if (!value) continue;
        chunks.push(value);
        received += value.length;
        onProgress?.(received / total);
    }

    const merged = new Uint8Array(received);
    let offset = 0;
    for (const chunk of chunks) {
        merged.set(chunk, offset);
        offset += chunk.length;
    }
    return merged.buffer;
}

