// 原生 toBase64（Chrome 140+）實測比 FileReader 快約 12 倍，沒有才退回 FileReader
const hasNativeToBase64 = typeof (Uint8Array.prototype as any).toBase64 === 'function';

async function uint8ArrayToBase64(bytes: Uint8Array): Promise<string> {
    if (hasNativeToBase64) return (bytes as any).toBase64() as string;
    return await blobToBase64(bytes);
}

function blobToBase64(bytes: Uint8Array): Promise<string> {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onloadend = () => {
            const base64 = (reader.result as string).split(',')[1];
            resolve(base64);
        };
        reader.onerror = reject;
        reader.readAsDataURL(new Blob([bytes as unknown as BlobPart]));
    });
}

function wordArrayToUint8Array(wordArray: CryptoJS.lib.WordArray): Uint8Array {
    const length = wordArray.sigBytes;
    const words = wordArray.words;
    const u8_array = new Uint8Array(length);

    // 逐 word 展開，避免逐 byte 的 Math.floor
    let i = 0;
    let w = 0;
    while (i + 4 <= length) {
        const word = words[w++];
        u8_array[i++] = (word >>> 24) & 0xff;
        u8_array[i++] = (word >>> 16) & 0xff;
        u8_array[i++] = (word >>> 8) & 0xff;
        u8_array[i++] = word & 0xff;
    }
    if (i < length) {
        const word = words[w];
        for (let b = 0; i < length; b++, i++) {
            u8_array[i] = (word >>> (24 - b * 8)) & 0xff;
        }
    }

    return u8_array;
}

async function getDecrypt() {
    if (!GlobalStore.apiUrl) {
        console.log("Waiting for API URL...");
        await waitForApiUrl();
    }
    const url = `${GlobalStore.apiUrl}static/jmapp3apk/encrypt_key.json`;
    try {
        const response = await fetch(url);
        const result = await response.json();
        return result;
    } catch (error) {
        console.error("Error fetching the data:", error);
    }
}

function hexToUint8Array(hex: string): Uint8Array {
    const bytes = new Uint8Array(hex.length >> 1);
    for (let i = 0; i < bytes.length; i++) {
        bytes[i] = parseInt(hex.substr(i * 2, 2), 16);
    }
    return bytes;
}

// AES-256-CBC 解密：優先用原生 WebCrypto，純 JS 的 CryptoJS 只當退路（慢數十倍）
async function decryptAesCBC(encryptedBuffer: ArrayBuffer, json: { ivHex: string, keyHex: string; }): Promise<Uint8Array> {
    if (!json?.keyHex || !json?.ivHex) throw new Error('[OTA] 取不到解密金鑰');

    const subtle = window.crypto?.subtle; // 非安全環境／舊 WebView 可能沒有
    if (subtle) {
        try {
            const key = await subtle.importKey(
                'raw',
                hexToUint8Array(json.keyHex),
                { name: 'AES-CBC' },
                false,
                ['decrypt'],
            );
            const plain = await subtle.decrypt(
                { name: 'AES-CBC', iv: hexToUint8Array(json.ivHex) },
                key,
                encryptedBuffer,
            );
            return new Uint8Array(plain);
        } catch (err) {
            console.warn('[OTA] WebCrypto 解密失敗，改用 CryptoJS', err);
        }
    }
    return decryptAesCbcWithCryptoJS(encryptedBuffer, json);
}

function decryptAesCbcWithCryptoJS(encryptedBuffer: ArrayBuffer, json: { ivHex: string, keyHex: string; }): Uint8Array {
    const { keyHex, ivHex } = json;

    const key = CryptoJS.enc.Hex.parse(keyHex);
    const iv = CryptoJS.enc.Hex.parse(ivHex);

    const encryptedWords = CryptoJS.lib.WordArray.create(new Uint8Array(encryptedBuffer) as any);
    const cipherParams = CryptoJS.lib.CipherParams.create({ ciphertext: encryptedWords });
    const decrypted = CryptoJS.AES.decrypt(
        cipherParams,
        key,
        {
            iv,
            mode: CryptoJS.mode.CBC,
            padding: CryptoJS.pad.Pkcs7,
        }
    );
    return wordArrayToUint8Array(decrypted);
}

/* ------------------------------------------------------------------ */
/* Unzip to Cache/update_<ver>/...                                    */
/* ------------------------------------------------------------------ */

async function unzipToCache(
    data: Uint8Array,
    folder: string,
    onProgress?: (done: number, total: number) => void,
    concurrency = 6,
) {
    const zip = await JSZip.loadAsync(data);
    // 「不存在」正常，「刪不掉」不能放過：殘留舊檔會和新檔混成壞 bundle
    let folderExists = true;
    try {
        await Filesystem.stat({ path: folder, directory: Directory.Cache });
    } catch {
        folderExists = false;
    }
    if (folderExists) {
        await Filesystem.rmdir({ path: folder, directory: Directory.Cache, recursive: true });
        console.log(`📁 Removed existing folder: ${folder}`);
    }
    // 建立根目錄
    try {
        await Filesystem.mkdir({ path: folder, directory: Directory.Cache, recursive: true });
    } catch (e) {
        console.warn(`⚠️ Failed to create folder ${folder}`, e);
    }

    // 只走訪 zip 一次，同時收集檔案與目錄
    const files: { relPath: string; file: any; }[] = [];
    const dirSet = new Set<string>();
    zip.forEach((relPath: string, file: any) => {
        if (file.dir) return;
        files.push({ relPath, file });
        const lastSlashIndex = relPath.lastIndexOf('/');
        if (lastSlashIndex !== -1) {
            dirSet.add(`${folder}/${relPath.substring(0, lastSlashIndex)}`);
        }
    });

    // 依深度序列建立：並行 recursive mkdir 會搶建同一層父目錄，失敗被吞掉後寫檔就報
    // Missing parent directory。目錄只十幾個，平行化的價值在後面的寫檔
    const allDirs = new Set<string>();
    dirSet.forEach((dirPath) => {
        const parts = dirPath.split('/');
        for (let i = 1; i <= parts.length; i++) allDirs.add(parts.slice(0, i).join('/'));
    });
    const orderedDirs = [...allDirs].sort((a, b) => a.split('/').length - b.split('/').length);
    for (const dirPath of orderedDirs) {
        try {
            // 父目錄前一輪已經建好，所以不需要 recursive
            await Filesystem.mkdir({ path: dirPath, directory: Directory.Cache, recursive: false });
        } catch (err) {
            // 只容忍「已存在」，其餘要往外丟，不然又變成沉默失敗
            if (!/exist/i.test(String((err as Error)?.message ?? err))) throw err;
        }
    }

    // worker pool：誰先寫完誰領下一個，不必整批等最慢的檔案
    const total = files.length;
    let cursor = 0;
    let done = 0;
    const worker = async () => {
        for (; ;) {
            const index = cursor++;
            if (index >= total) return;
            const { relPath, file } = files[index];
            const dest = `${folder}/${relPath}`;
            try {
                const content: Uint8Array = await file.async('uint8array');
                await Filesystem.writeFile({
                    path: dest,
                    data: await uint8ArrayToBase64(content),
                    directory: Directory.Cache,
                    recursive: true,
                });
            } catch (err) {
                console.error(`❌ Failed to write file: ${relPath}`, err);
                // 缺檔的新版本是壞的，直接失敗讓外層保留舊版
                throw err;
            }
            done++;
            onProgress?.(done, total);
        }
    };
    await Promise.all(Array.from({ length: Math.min(concurrency, total) }, worker));
}


/* ------------------------------------------------------------------ */
/* Simple MIME helper                                                 */
/* ------------------------------------------------------------------ */

function getMime(path: string): string {
    const ext = path.split('.').pop()?.toLowerCase();
    switch (ext) {
        case 'html': return 'text/html';
        case 'js': return 'application/javascript';
        case 'css': return 'text/css';
        case 'json': return 'application/json';
        case 'png': return 'image/png';
        case 'jpg':
        case 'jpeg': return 'image/jpeg';
        case 'svg': return 'image/svg+xml';
        case 'woff': return 'font/woff';
        case 'woff2': return 'font/woff2';
        default: return 'application/octet-stream';
    }
}

/* ------------------------------------------------------------------ */
/* Local WebServer → http://localhost:18181                           */
/* ------------------------------------------------------------------ */

async function startLocalServer(baseDir: string) {
    try {
        const { uri } = await Filesystem.stat({
            directory: Directory.Cache,
            path: `${baseDir}/index.html`,
        });
        const basePath = uri.replace(/^file:\/\//, '').replace(/\/index\.html$/, '');
        console.log('[OTA] Base path:', basePath);

        await WebView.setServerBasePath({ path: basePath });

        // Optional: 清除快取與 service worker
        if ('serviceWorker' in navigator) {
            const regs = await navigator.serviceWorker.getRegistrations();
            await Promise.all(regs.map(r => r.unregister()));
            console.log('[OTA] Unregistered service workers');
        }
        if ('caches' in window) {
            const keys = await caches.keys();
            await Promise.all(keys.map(k => caches.delete(k)));
            console.log('[OTA] Cleared caches');
        }

        // 永續化失敗也照樣 reload：路徑這次已切好，下次啟動由 getLocalVersion 補救
        await persistServerBasePathWithRetry();

        window.location.reload();
    } catch (error) {
        console.warn('[OTA] 無法啟用本地更新資源，可能缺少 index.html', error);
    }
}

/* ------------------------------------------------------------------ */
/* One‑shot flow: download → unzip → serve                            */
/* ------------------------------------------------------------------ */

export async function runOtaFlow(dispatch: AppDispatch, state: RootState) {
    try {
        const newVer = state.hotUpdate.newVersion;
        const folder = `update_${newVer}`;

        // 進度分配：下載 0~55、解密 55~65、解壓寫檔 65~99
        let lastReported = -1;
        const report = (value: number) => {
            const next = Math.max(0, Math.min(99, Math.round(value)));
            if (next === lastReported) return; // 同一個整數不重複 dispatch
            lastReported = next;
            dispatch(SET_HOT_UPDATE_MODAL_PROGRESS(next));
        };

        report(1);
        // 金鑰檔很小，和下載並行取回
        const [buf, json] = await Promise.all([
            downloadBuildZip((ratio) => report(ratio * 55)),
            getDecrypt(),
        ]);
        report(55);

        const decryptedBuf = await decryptAesCBC(buf, json);
        report(65);

        // 直接把 Uint8Array 給 JSZip，不多複製一份
        await unzipToCache(decryptedBuf, folder, (done, total) =>
            report(65 + (done / total) * 34)
        );

        // ✅ 清除舊版本快取
        await cleanOldCaches(newVer);

        // ✅ 儲存版本資訊
        await setLocalVersion(newVer);
        console.log("[✅] 已儲存 local version:", newVer);
        await Preferences.set({ key: `update_${newVer}`, value: 'true' });

        dispatch(SET_HOT_UPDATE_MODAL_PROGRESS(100));
        dispatch(SET_HOT_UPDATE_ENABLED(false));
        dispatch(SET_HOT_UPDATE_MODAL_PROGRESS(0));

        // ✅ 切換至新版本的本地資源路徑
        await startLocalServer(`${folder}/build`);
    } catch (err) {
        dispatch(SET_SHOW_HOT_UPDATE_MODAL(false));
        alert("⚠️ 更新失敗，將繼續使用舊版本");
        console.error('[OTA] update failed – keep old version', err);
    }
}

// 🔽 清除舊版本資料夾（非必要，但推薦）
async function cleanOldCaches(currentVersion: string) {
    const keys = await Preferences.keys();
    for (const key of keys.keys) {
        if (/^update_\d+\.\d+\.\d+/.test(key) && key !== `update_${currentVersion}`) {
            const folder = `${key}/build`;
            try {
                await Filesystem.rmdir({ path: folder, directory: Directory.Cache, recursive: true });
                await Preferences.remove({ key });
                console.log(`🧹 清除舊版本快取: ${key}`);
            } catch (e) {
                console.warn(`⚠️ 清除失敗: ${key}`, e);
            }
        }
    }
}

/* ------------------------------------------------------------------ */
/* App foreground listener                                            */
/* ------------------------------------------------------------------ */

export async function setupOtaChecker(dispatch: AppDispatch) {
    try {
        const ver = await needUpdate();
        if (ver) {
            dispatch(SET_SHOW_HOT_UPDATE_MODAL(true));
            dispatch(SET_NEW_VERSION(ver));
            console.log(`[OTA] updating to v${ver}`);
        } else {
            dispatch(SET_SHOW_HOT_UPDATE_MODAL(false));
        }
    } catch (err) {
        console.error('[OTA] update failed – keep old version', err);
    }
}

export async function checkCache(baseDir: string): Promise<string | null> {
    try {
        const { uri } = await Filesystem.stat({
            directory: Directory.Cache,
            path: `${baseDir}/index.html`
        });
        console.log('檔案存在:', uri);
        return uri;
    } catch (error) {
        console.warn('找不到檔案:', error);
        return null;
    }
}

export async function initHotUpdate(dispatch: AppDispatch) {
    try {
        const isNative = Capacitor.isNativePlatform();
        if (!isNative) {
            dispatch(SET_SHOW_HOT_UPDATE_MODAL(false));
            localStorage.setItem("newVersion", DEFAULT_VERSION);
            return;
        }
        let localVersion = await getLocalVersion(); // ✅ 總是透過 helper 取得版本

        if (!localVersion || localVersion === '') {
            localVersion = DEFAULT_VERSION;
            await setLocalVersion(localVersion);
            console.log("🆕 第一次啟動，設定為預設版本");
        }

        const cacheFolder = `update_${localVersion}/build`;
        const cachedFlag = (await Preferences.get({ key: `update_${localVersion}` })).value;

        // 檢查遠端版本
        const remoteVersion = await fetchRemoteVersion();
        if (isNewerVersion(remoteVersion, localVersion)) {
            console.log(`🚀 發現新版本：${remoteVersion}，本地版本：${localVersion}`);
            dispatch(SET_NEW_VERSION(remoteVersion));
            dispatch(SET_SHOW_HOT_UPDATE_MODAL(true));
            localStorage.setItem("newVersion", remoteVersion);
            return;
        }

        // 沒有新版本 → 檢查快取
        if (cachedFlag === "true") {
            const fileUri = await checkCache(cacheFolder);
            if (fileUri) {
                console.log("✅ 快取有效，使用快取版本");
                return dispatch(SET_SHOW_HOT_UPDATE_MODAL(false));
            } else {
                console.warn("⚠️ 快取標記存在，但實際遺失");
            }
        }

        // 無快取也無新版本 → 保守處理
        console.log("🔄 快取遺失，強制再檢查更新");
        await setupOtaChecker(dispatch);

    } catch (err) {
        console.error("❌ 初始化更新流程失敗:", err);
        dispatch(SET_SHOW_HOT_UPDATE_MODAL(false));
    }
}




