import { useEffect } from "react";
import { useLocation, useNavigate } from "react-router-dom";

// 後端 HTML 的站內漫畫連結是官網格式 /album/<id>/，前端沒這個路由會掉到 ErrorPage
const ALBUM_PATH = /^\/album\/(\d+)(?:\/.*)?$/;

// 全域攔截 <a> 點擊，改走前端路由
const useInternalLinkInterceptor = () => {
  const navigate = useNavigate();
  const location = useLocation();

  useEffect(() => {
    const handleClick = (event: MouseEvent) => {
      if (event.defaultPrevented || event.button !== 0) return;
      if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;

      const anchor = (event.target as HTMLElement)?.closest("a");
      if (!anchor) return;

      const href = anchor.getAttribute("href");
      if (!href) return;

      // 有 payment? 一律導回站內 /pay，並保留原本的 query string
      if (href.includes("payment?")) {
        const query = href.split("payment?")[1] || "";
        event.preventDefault();
        navigate(query ? `/pay?${query}` : "/pay");
        return;
      }

      // 擺在 _blank 檢查前：後端 HTML 常帶 target="_blank"，放行會讓 WebView 另開視窗
      const album = href.match(ALBUM_PATH);
      if (album) {
        event.preventDefault();
        // 不寫 fromPage：那是 Blogs / Library 返回鍵的來源，蓋掉它們會繞不出去
        const from = `${location.pathname}${location.search}`;
        navigate(`/comic/detail?id=${album[1]}`, { state: { from } });
        return;
      }

      if (anchor.target === "_blank" || anchor.hasAttribute("download")) return;

      if (!href.startsWith("/") || href.startsWith("//")) return;

      event.preventDefault();
      navigate(href);
    };

    document.addEventListener("click", handleClick);
    return () => document.removeEventListener("click", handleClick);
  }, [navigate, location.pathname, location.search]);
};

export default useInternalLinkInterceptor;
