import { Component, ErrorInfo, ReactNode } from "react";
import i18n from "../../i18n";
import { isChunkLoadError } from "../../utils/lazyWithRetry";

interface Props {
  children: ReactNode;
}

interface State {
  error: Error | null;
}

// 沒有 ErrorBoundary 時，render 階段任何一個 throw 都會讓 React 卸載整棵 tree，
// 畫面變全白又點不動，使用者只能強制關掉 App。這裡攔下來至少還給一個能操作的畫面。
class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null };

  static getDerivedStateFromError(error: Error): State {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    console.error("[ErrorBoundary]", error, info.componentStack);
  }

  handleReload = () => {
    window.location.reload();
  };

  handleGoHome = () => {
    // 用整頁跳轉而不是 router，壞掉的 chunk／state 一起重新來
    window.location.href = "/";
  };

  render() {
    const { error } = this.state;
    if (!error) return this.props.children;

    const chunkFailed = isChunkLoadError(error);

    return (
      <div className="fixed inset-0 z-[9999] flex flex-col items-center justify-center gap-4 bg-defaultBg px-8 text-center text-gy dark:bg-bk dark:text-tgy">
        <p className="text-lg">{i18n.t("crash.title")}</p>
        <p className="text-sm opacity-70">{chunkFailed ? i18n.t("crash.chunk_hint") : i18n.t("crash.generic_hint")}</p>
        <div className="flex gap-3">
          <button className="rounded bg-og px-6 py-2 text-white" onClick={this.handleReload}>
            {i18n.t("crash.reload")}
          </button>
          <button className="rounded border border-current px-6 py-2" onClick={this.handleGoHome}>
            {i18n.t("crash.go_home")}
          </button>
        </div>
        <p className="max-w-full break-words text-xs opacity-40">{error.message}</p>
      </div>
    );
  }
}

export default ErrorBoundary;
