import { ComponentType, lazy } from "react";

// 熱更新換過 serverBasePath、或行動網路斷一下，動態 import 就抓不到 chunk。
// React.lazy 的 factory 失敗後會把 rejected 狀態記住、之後 render 都直接 throw，
// 整棵 tree 被卸載就是白屏且點不動，只能重開 App。所以這裡先重試，再退到 reload 一次。

const RETRY_COUNT = 2;
const RETRY_DELAY_MS = 500;
// key 帶上版本：熱更新換版後是全新的 bundle，自救額度重新給一次
const RELOAD_FLAG_KEY = `chunkLoadReloaded:${process.env.REACT_APP_VERSION || "0"}`;

const CHUNK_ERROR_PATTERN =
  /Loading chunk|Loading CSS chunk|ChunkLoadError|dynamically imported module|Importing a module script failed|error loading dynamically imported/i;

const isChunkLoadError = (err: unknown) => {
  if (!err) return false;
  const err2 = err as { name?: string; message?: string; };
  return CHUNK_ERROR_PATTERN.test(`${err2.name ?? ""} ${err2.message ?? String(err)}`);
};

// sessionStorage 在部分 WebView／隱私模式會直接 throw，不能讓它弄壞載入流程
const safeSession = {
  get(key: string) {
    try {
      return sessionStorage.getItem(key);
    } catch {
      return null;
    }
  },
  set(key: string, value: string) {
    try {
      sessionStorage.setItem(key, value);
    } catch {
      /* ignore */
    }
  },
};

const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

export function lazyWithRetry<T extends ComponentType<any>>(factory: () => Promise<{ default: T; }>) {
  return lazy(async () => {
    let lastError: unknown;

    for (let attempt = 0; attempt <= RETRY_COUNT; attempt++) {
      try {
        return await factory();
      } catch (err) {
        lastError = err;
        if (!isChunkLoadError(err) || attempt === RETRY_COUNT) break;
        await sleep(RETRY_DELAY_MS * (attempt + 1));
      }
    }

    // 重試還是失敗：chunk 檔很可能真的不在了（熱更新換版／解壓少寫檔），
    // reload 會重新抓 index.html 拿到新的檔名。
    // 一個 session 只自救一次：bundle 真的壞掉時不會在「好的頁 → 壞的頁」之間反覆 reload，
    // 第二次起交給 ErrorBoundary 顯示可操作的錯誤畫面。
    if (isChunkLoadError(lastError) && !safeSession.get(RELOAD_FLAG_KEY)) {
      safeSession.set(RELOAD_FLAG_KEY, String(Date.now()));
      window.location.reload();
      // reload 需要時間，先掛住別把錯誤丟出去，不然 ErrorBoundary 會先閃一下
      await sleep(10000);
    }

    throw lastError;
  });
}

export { isChunkLoadError };
