import React, { Suspense, useEffect } from "react";
import { Route, Routes, useLocation } from "react-router-dom";
import { useGlobalConfig } from "./GlobalContext";
import { useBackButtonExit, useDevtoolsBlocker, usePWAProtection } from "./Hooks/useAppGuards";
import { AuthChecker } from "./Hooks/useAuth";
import useInternalLinkInterceptor from "./Hooks/useInternalLinkInterceptor";
import usePageTracking from "./Hooks/usePageTrack";
import useScrollRestoration from "./Hooks/useScrollRestoration";
import { FETCH_HOST } from "./api/ApiEndpointUtil";
import { ConfirmAlert } from "./components/Alert/Alert";
import Loading from "./components/Common/Loading";
import ErrorBoundary from "./components/Common/ErrorBoundary";
import ViewportMeta from "./components/Common/ViewportMeta";
import { useAppDispatch } from "./store/hooks";
import { getRandomItems } from "./utils/Function";
import { getLocalVersion, initHotUpdate } from "./utils/hotModule";
import { lazyWithRetry } from "./utils/lazyWithRetry";

const Main = lazyWithRetry(() => import("./pages/Main/Main"));
const Week = lazyWithRetry(() => import("./pages/Main/Week"));
const Blog = lazyWithRetry(() => import("./pages/Blogs/Blogs"));
const BlogsDetail = lazyWithRetry(() => import("./pages/Blogs/BlogsDetail"));
const Search = lazyWithRetry(() => import("./pages/Search/Search"));
const Detail = lazyWithRetry(() => import("./pages/Comic/Detail"));
const Read = lazyWithRetry(() => import("./pages/Comic/Read"));
const Download = lazyWithRetry(() => import("./pages/Comic/Download"));
const Comic = lazyWithRetry(() => import("./pages/Comic/Comic"));
const Library = lazyWithRetry(() => import("./pages/Library/Library"));
const LibraryList = lazyWithRetry(() => import("./pages/Library/LibraryList"));
const LibraryDetail = lazyWithRetry(() => import("./pages/Library/LibraryDetail"));
const Movies = lazyWithRetry(() => import("./pages/Movies/Movies"));
const MoviesPlayer = lazyWithRetry(() => import("./pages/Movies/MoviesPlayer"));
const Daily = lazyWithRetry(() => import("./pages/Member/Daily"));
const Games = lazyWithRetry(() => import("./pages/Categories/Games"));
const Categories = lazyWithRetry(() => import("./pages/Categories/Categories"));
const Member = lazyWithRetry(() => import("./pages/Member/Member"));
const Forum = lazyWithRetry(() => import("./pages/Forum/Forum"));
const Novels = lazyWithRetry(() => import("./pages/Novel/Novels"));
const NovelDetail = lazyWithRetry(() => import("./pages/Novel/NovelDetail"));
const NovelRead = lazyWithRetry(() => import("./pages/Novel/NovelRead"));
const ErrorPage = lazyWithRetry(() => import("./pages/Main/ErrorPage"));
const TestComponent = lazyWithRetry(() => import("./pages/TestComponent"));
const Pay = lazyWithRetry(() => import("./pages/Sponsor/Pay"));
const Contact = lazyWithRetry(() => import("./pages/Contact/Contact"));

const fetchHostData = async () => {
  const apiUrl = await FETCH_HOST();
  return apiUrl;
};

const App = () => {
  const { config, setConfig } = useGlobalConfig();
  const { exit, setExit, confirmExit } = useBackButtonExit(); // 離開 App 提示框
  const dispatch = useAppDispatch();
  const location = useLocation();

  // 紀錄滾動位置
  useScrollRestoration();
  //ga
  usePageTracking();
  // 禁用瀏覽器
  usePWAProtection();
  // 禁用F12
  useDevtoolsBlocker();
  // 全域攔截站內 <a href="/xxx"> 點擊，改走前端路由
  useInternalLinkInterceptor();

  useEffect(() => {
    if (process.env.REACT_APP_ENV === "production") {
      console.log("Running in Production Mode!");
    } else if (process.env.REACT_APP_ENV === "development") {
      console.log("Running in Development Mode!");
    }
    // 攔截同步 JS 錯誤
    window.onerror = function (message, source, lineno, colno, error) {
      console.warn("JS 錯誤:", { message, source, lineno, colno, error });
      // showErrorModal(`\n${defaultErrorMsg}`);
      // setTimeout(() => {
      //   window.location.href = "/";
      // }, 60000);
    };

    // 攔截未處理的 Promise rejection（chunk 載入失敗、thunk 噴錯都走這裡）
    const handleRejection = (e: PromiseRejectionEvent) => {
      console.warn("未處理的 Promise 錯誤:", e.reason);
    };
    window.addEventListener("unhandledrejection", handleRejection);
    return () => window.removeEventListener("unhandledrejection", handleRejection);
  }, []);

  // host init
  useEffect(() => {
    fetchHostData().then((apiUrl) => {
      if (apiUrl) {
        const filteredServers = apiUrl.jm3_Server.filter(([_, name]: [string, string]) => name !== "線路5");
        const { items } = getRandomItems(filteredServers);
        const newUrl = `https://${items}/`;
        setConfig((prev) => ({ ...prev, hostReady: true, host: newUrl }));
      }
      // if (process.env.REACT_APP_ENV === "development" && window.location.hostname.includes("localhost")) {
      //   setConfig((prev) => ({
      //     ...prev,
      //     showdone: true,
      //     defaultCoverImg: "/images/signList/done-icon.png",
      //   }));
      //   localStorage.removeItem("adsList");
      //   localStorage.removeItem("adsContent");
      // }
    });
  }, []);

  // hot update
  useEffect(() => {
    if (config.hostReady) {
      initHotUpdate(dispatch);

      const getVersion = async () => {
        const v = await getLocalVersion();
        setConfig((prev: any) => ({ ...prev, version: v }));
      };

      getVersion();
    }
  }, [config.hostReady]);

  return (
    <>
      <ViewportMeta />
      <AuthChecker setConfig={setConfig} />
      <div className="safe-area">
        {/* key 帶 pathname：換頁就重置，才不會一次錯誤就卡在錯誤畫面出不來 */}
        <ErrorBoundary key={location.pathname}>
          <Suspense fallback={<Loading />}>
            <Routes>
              <Route path="/" element={<Main />} />
              <Route path="/blogs" element={<Blog />} />
              <Route path="/blogs/detail" element={<BlogsDetail />} />
              <Route path="/week" element={<Week />} />
              <Route path="/search" element={<Search />} />
              <Route path="/comic" element={<Comic />} />
              <Route path="/comic/detail" element={<Detail />} />
              <Route path="/comic/detail/download" element={<Download />} />
              <Route path="/comic/detail/read" element={<Read />} />
              <Route path="/library" element={<Library />} />
              <Route path="/library/list" element={<LibraryList />} />
              <Route path="/library/list/detail" element={<LibraryDetail />} />
              <Route path="/categories" element={<Categories />} />
              <Route path="/forum" element={<Forum />} />
              <Route path="/movies" element={<Movies />} />
              <Route path="/movies/:id" element={<MoviesPlayer />} />
              <Route path="/games" element={<Games />} />
              <Route path="/member" element={<Member />} />
              <Route path="/daily" element={<Daily />} />
              <Route path="/novels" element={<Novels />} />
              <Route path="/pay" element={<Pay />} />
              <Route path="/novels/detail" element={<NovelDetail />} />
              <Route path="/novels/detail/read" element={<NovelRead />} />
              <Route path="/contact" element={<Contact />} />
              <Route path="*" element={<ErrorPage />} />
              <Route path="/test" element={<TestComponent />} />
            </Routes>
          </Suspense>
        </ErrorBoundary>
      </div>
      {exit.alert && <ConfirmAlert edit={exit} setEdit={setExit} handleAction={confirmExit} />}
    </>
  );
};

export default App;
